const input = $input.first().json;
const env = typeof $env !== 'undefined' ? $env : {};
const founderChatId = String(env.FOUNDER_TELEGRAM_CHAT_ID || '').trim();
const updateMessage = input.message || input.edited_message || input;
const chatId = String((updateMessage.chat && updateMessage.chat.id) || input.chat_id || '').trim();
const text = String(updateMessage.text || updateMessage.caption || '').trim();

function reply(status, message, extra = {}) {
  return [{ json: { status, chatId, reply: message, ...extra } }];
}

if (!founderChatId) {
  return reply('not_configured', 'Telegram import is not configured. Set FOUNDER_TELEGRAM_CHAT_ID in n8n.');
}

if (chatId !== founderChatId) {
  return reply('unauthorized', 'Not authorized.');
}

const supportedCategories = new Map([
  ['motherboard', 'Motherboard'],
  ['gpu', 'GPU'],
  ['cpu', 'CPU'],
  ['ram', 'RAM'],
  ['storage', 'Storage'],
  ['psu', 'PSU'],
  ['case', 'Case'],
  ['cooler', 'Cooler']
]);

const categoryCommand = text.match(/^(Motherboard|GPU|CPU|RAM|Storage|PSU|Case|Cooler)\s+(https?:\/\/\S+)/i);
const explicitCategory = categoryCommand ? supportedCategories.get(categoryCommand[1].toLowerCase()) : null;
const urlMatch = text.match(/https?:\/\/[^\s<>"']+/i);

if (!urlMatch) {
  return reply('url_required', 'Send one product URL, or use: Motherboard https://store.example/product');
}

function sanitizeUrl(rawUrl) {
  const parsed = new URL(rawUrl);
  parsed.hash = '';
  const removable = new Set(['fbclid', 'gclid', 'msclkid', '_hsenc', '_hsmi', 'ref', 'tag', 'spm', 'scm']);
  for (const key of [...parsed.searchParams.keys()]) {
    if (key.toLowerCase().startsWith('utm_') || removable.has(key.toLowerCase())) {
      parsed.searchParams.delete(key);
    }
  }
  return parsed.toString();
}

function inferSource(hostname) {
  const host = hostname.toLowerCase().replace(/^www\./, '');
  if (host === 'pczonesa.com' || host.endsWith('.pczonesa.com')) return 'PCZone Saudi';
  if (host === 'microless.com' || host.endsWith('.microless.com')) return 'Microless Saudi';
  if (host === 'mtc.com.sa' || host.endsWith('.mtc.com.sa') || host === 'mtcsaudi.com') return 'MTC KSA';
  if (host === 'noon.com' || host.endsWith('.noon.com')) return 'Noon Saudi';
  if (host === 'amazon.sa' || host.endsWith('.amazon.sa')) return 'Amazon.sa';
  return null;
}

function inferCategory(url) {
  const slug = `${url.hostname} ${url.pathname}`.toLowerCase();
  const checks = [
    ['Motherboard', /motherboard|\bb650\b|\bb760\b|\bx670\b|\ba620\b/],
    ['GPU', /\bgpu\b|graphics|\bvga\b|\brtx\b|radeon|\brx-/],
    ['CPU', /\bcpu\b|processor|ryzen|intel-core/],
    ['RAM', /\bram\b|memory|\bddr5\b|\bddr4\b/],
    ['Storage', /\bssd\b|\bnvme\b|\bm2\b|storage/],
    ['PSU', /\bpsu\b|power-supply|\b850w\b|\b750w\b/],
    ['Case', /\bcase\b|chassis|tower/],
    ['Cooler', /cooler|\baio\b|heatsink|thermalright|kraken/]
  ];
  return (checks.find(([, pattern]) => pattern.test(slug)) || [null])[0];
}

function stableHash(value) {
  let hash = 5381;
  for (let index = 0; index < value.length; index += 1) {
    hash = ((hash << 5) + hash) ^ value.charCodeAt(index);
  }
  return (hash >>> 0).toString(16);
}

let parsed;
let normalizedUrl;
try {
  normalizedUrl = sanitizeUrl(urlMatch[0]);
  parsed = new URL(normalizedUrl);
} catch (error) {
  return reply('invalid_url', 'That does not look like a valid product URL.');
}

const sourceName = inferSource(parsed.hostname);
if (!sourceName) {
  return reply('unsupported_domain', `Unsupported source domain: ${parsed.hostname}. Use PCZone, Microless, MTC KSA, Noon Saudi, or Amazon.sa product URLs only.`, { url: normalizedUrl });
}

const category = explicitCategory || inferCategory(parsed);
if (!category) {
  return reply('category_required', `I could not infer the category. Reply with a category command, for example: Motherboard ${normalizedUrl}`, { url: normalizedUrl, sourceName });
}

return [{
  json: {
    status: 'ready',
    chatId,
    url: normalizedUrl,
    category,
    sourceName,
    normalizedUrlHash: stableHash(normalizedUrl),
    reply: null
  }
}];

const preview = $input.first().json;
const base = $node['Validate Founder And URL'].json;
const sourcePolicy = String(preview.source_policy_status || '').toLowerCase();
const price = preview.item_price_sar ?? preview.price ?? null;
const hasPrice = price !== null && price !== undefined && String(price).trim() !== '';
const policyAllowed = !['blocked', 'unsupported'].includes(sourcePolicy);
const accepted = preview.accepted === true;
const reasons = Array.isArray(preview.rejected_reasons) ? preview.rejected_reasons : [];
const warnings = [preview.vat_status, preview.shipping_status, preview.warranty_status]
  .filter((value) => value && String(value).toLowerCase().includes('unknown'));

if (accepted && hasPrice && policyAllowed) {
  return [{
    json: {
      ...base,
      status: 'ingest_ready',
      preview,
      price,
      title: preview.normalized_name || preview.raw_title || 'Unknown product',
      vendor: preview.vendor_name || preview.source_name || base.sourceName,
      canonicalKey: preview.canonical_key || 'unknown',
      warnings
    }
  }];
}

const failed = [];
if (!accepted) failed.push('preview was not accepted');
if (!hasPrice) failed.push('price is missing');
if (!policyAllowed) failed.push(`source policy is ${sourcePolicy || 'unknown'}`);
if (reasons.length) failed.push(`reasons: ${reasons.join('; ')}`);

return [{
  json: {
    ...base,
    status: 'preview_rejected',
    preview,
    reply: [
      'Product URL was not ingested.',
      `Reason: ${failed.join(' | ') || 'unknown'}`,
      `Source policy: ${preview.source_policy_status || 'unknown'}`,
      `Category: ${base.category}`,
      `URL: ${base.url}`
    ].join('\n')
  }
}];

const ingest = $input.first().json;
const base = $node['Evaluate Preview'].json;
const preview = base.preview || {};
const warnings = [
  preview.vat_status ? `VAT: ${preview.vat_status}` : null,
  preview.shipping_status ? `Shipping: ${preview.shipping_status}` : null,
  preview.warranty_status ? `Warranty: ${preview.warranty_status}` : null
].filter(Boolean);
const price = preview.item_price_sar ?? preview.price ?? base.price ?? 'unknown';
const currency = preview.currency || 'SAR';
const ingestStatus = ingest.status || ingest.ingest_status || 'ingested';

return [{
  json: {
    chatId: base.chatId,
    reply: [
      'Product URL ingested.',
      `Title: ${base.title}`,
      `Vendor: ${base.vendor}`,
      `Category: ${base.category}`,
      `Price: ${price} ${currency}`,
      `Canonical key: ${base.canonicalKey}`,
      `Ingest status: ${ingestStatus}`,
      warnings.length ? `Warnings: ${warnings.join(' | ')}` : 'Warnings: none reported',
      `URL: ${base.url}`
    ].join('\n')
  }
}];
